* ngspice testbench for Op-Amp
.lib ${SKY130_PDK} tt

* Define default parameters for the parameterized netlist
.param W_xm28=2 L_xm28=0.5 W_xm1=2 L_xm1=0.5 W_xm2=2 L_xm2=0.5 W_xm3=4 L_xm3=0.5 W_xm4=4 L_xm4=0.5 W_xm5=2 L_xm5=0.5 W_xm6=2 L_xm6=0.5 W_xm7=2 L_xm7=0.5 W_xm8=2 L_xm8=0.5 W_xm9=2 L_xm9=0.5 W_xm10=2 L_xm10=0.5 W_xm11=4 L_xm11=0.5 W_xm12=4 L_xm12=0.5 W_xm13=2 L_xm13=0.5 W_xm14=2 L_xm14=0.5 W_xm15=2 L_xm15=0.5 W_xm16=4 L_xm16=0.5 W_xm18=4 L_xm18=0.5 W_xm19=4 L_xm19=0.5 W_xmsu2=2 L_xmsu2=0.5 W_xmsu1=2 L_xmsu1=0.5 W_xmsu3=2 L_xmsu3=0.5 W_xma4=2 L_xma4=0.5 W_xma3=2 L_xma3=0.5

* DUT Netlist
VDD VDD 0 1.8
Cbig1 vm 0 1e-05
Rbig1 vm Vout 1000000.0
xm28 N001 N001 N004 VDD sky130_fd_pr__pfet_01v8 w={W_xm28} l={L_xm28}
xm1 N010 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
xm2 N010 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
xm3 N001 vm N010 0 sky130_fd_pr__nfet_01v8 w={W_xm3} l={L_xm3}
xm4 N009 vp N010 0 sky130_fd_pr__nfet_01v8 w={W_xm4} l={L_xm4}
xm5 N004 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm5} l={L_xm5}
xm6 N009 N001 N005 VDD sky130_fd_pr__pfet_01v8 w={W_xm6} l={L_xm6}
xm7 N005 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
xm8 N002 N002 N006 VDD sky130_fd_pr__pfet_01v8 w={W_xm8} l={L_xm8}
xm9 N011 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm9} l={L_xm9}
xm10 N011 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm10} l={L_xm10}
xm11 N002 N009 N011 0 sky130_fd_pr__nfet_01v8 w={W_xm11} l={L_xm11}
xm12 N003 N001 N011 0 sky130_fd_pr__nfet_01v8 w={W_xm12} l={L_xm12}
xm13 N006 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm13} l={L_xm13}
xm14 N003 N002 N007 VDD sky130_fd_pr__pfet_01v8 w={W_xm14} l={L_xm14}
xm15 N007 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm15} l={L_xm15}
xm16 Vout Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm16} l={L_xm16}
xm18 Vout N003 N008 VDD sky130_fd_pr__pfet_01v8 w={W_xm18} l={L_xm18}
xm19 N008 N003 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm19} l={L_xm19}
Cc1 N003 N001 2.4e-13
Cc2 Vout N005 2.4e-12
X_U1 Vbiasn Vbiasp VDD 0 SUB_1
Cload Vout 0 1e-12

.subckt SUB_1 Vbiasn Vbiasp VDD GND
  xmsu2 N002 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xmsu2} l={L_xmsu2}
  xmsu1 N002 Vbiasn GND 0 sky130_fd_pr__nfet_01v8 w={W_xmsu1} l={L_xmsu1}
  xmsu3 Vbiasp N002 Vbiasn 0 sky130_fd_pr__nfet_01v8 w={W_xmsu3} l={L_xmsu3}
  xm3 Vbiasn Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm1} l={L_xm1}
  xm4 N003 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm2} l={L_xm2}
  xm1 Vbiasn Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  R1 N004 0 5.5k
  xma4 Vbiasp N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
  xma3 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
  xm5 N001 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
  xm7 VDD Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
  xm8 0 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm8} l={L_xm8}
  xm2 Vbiasp Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1

* Stimulus
Vinp vp 0 dc 0.9 ac 1

.control
  * DC Operating Point
  op
  let power = -i(VDD) * 1.8
  print power

  * AC Analysis
  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  let phase = 180/PI * cph(v(Vout))

  meas ac aoldc find gain_db at=10
  meas ac fun when gain_db=0 fall=1
  meas ac pm find phase when gain_db=0 fall=1

  print aoldc fun pm
.endc
.end

